<?php
if(session_status()===PHP_SESSION_NONE)session_start();require_once '../includes/config.php';require_once '../includes/database.php';require_once '../includes/auth.php';$db=new Database();$auth=new Auth($db);$auth->requireRole(['counter_staff','handling_staff','supervisor','system_admin']);$pdo=$db->getConnection();$byStatus=$pdo->query("SELECT status,COUNT(*) total,AVG(weight) avg_weight FROM baggage GROUP BY status ORDER BY total DESC")->fetchAll();$byFlight=$pdo->query("SELECT f.flight_number,COUNT(b.id) baggage_count,SUM(b.status='delayed') delayed,SUM(b.status='lost') lost FROM flights f LEFT JOIN baggage b ON b.flight_id=f.id GROUP BY f.id,f.flight_number ORDER BY baggage_count DESC LIMIT 20")->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reports</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><div class="container py-5"><a href="dashboard.php">← Dashboard</a><h2>Operational Reports</h2><div class="row g-4"><div class="col-lg-5"><div class="card"><div class="card-header">Baggage by status</div><table class="table mb-0"><tr><th>Status</th><th>Total</th><th>Avg weight</th></tr><?php foreach($byStatus as $r):?><tr><td><?=htmlspecialchars($r['status'])?></td><td><?=intval($r['total'])?></td><td><?=round((float)$r['avg_weight'],1)?></td></tr><?php endforeach;?></table></div></div><div class="col-lg-7"><div class="card"><div class="card-header">Flights</div><table class="table mb-0"><tr><th>Flight</th><th>Baggage</th><th>Delayed</th><th>Lost</th></tr><?php foreach($byFlight as $r):?><tr><td><?=htmlspecialchars($r['flight_number'])?></td><td><?=intval($r['baggage_count'])?></td><td><?=intval($r['delayed'])?></td><td><?=intval($r['lost'])?></td></tr><?php endforeach;?></table></div></div></div></div></div></body></html>